css:
.switch-container {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 16px;
  border: 1px dashed #666;
  border-radius: 8px;
  background-color: #1a1a1a;
  max-width: 500px;
  box-shadow: 0 0 2px rgba(255, 255, 255, 0.1);
}

.switch {
  position: relative;
  display: inline-block;
  width: 32px;
  height: 16px;
  margin-top: 4px;
  flex-shrink: 0;
}

.switch .input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #444;
  border-radius: 20px;
  transition: 0.2s;
}

.slider::before {
  position: absolute;
  content: "";
  height: 12px;
  width: 12px;
  left: 2px;
  bottom: 2px;
  background-color: white;
  border-radius: 50%;
  transition: 0.2s;
}

.input:checked + .slider {
  background-color: #4f46e5; /* Tailwind's primary/indigo */
}

.input:checked + .slider::before {
  transform: translateX(16px);
}

.content {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.icon {
  flex-shrink: 0;
}

.text-content {
  display: grid;
  gap: 6px;
}

.main-label {
  font-weight: 600;
  font-size: 14px;
  color: #ccc;
}

.sublabel {
  font-size: 12px;
  color: #aaa;
  font-weight: 400;
  margin-left: 4px;
}

.description {
  font-size: 12px;
  color: #888;
}
